import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"困","description":"焦氏易林注 - 困","frontmatter":{"title":"困","description":"焦氏易林注 - 困"},"headers":[],"relativePath":"classics/jiaoyilin/047.md","filePath":"classics/jiaoyilin/047.md"}'),l={name:"classics/jiaoyilin/047.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="困" tabindex="-1">困 <a class="header-anchor" href="#困" aria-label="Permalink to “困”">​</a></h1><h3 id="困-1" tabindex="-1">困 <a class="header-anchor" href="#困-1" aria-label="Permalink to “困”">​</a></h3><h3 id="困之乾" tabindex="-1">困之乾 <a class="header-anchor" href="#困之乾" aria-label="Permalink to “困之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>鳥鵲食谷，張口受哺。蒙被恩德，長大成就。柔順利貞，君臣合好。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>詳《履》之《鹹》。</p><h3 id="困之坤" tabindex="-1">困之坤 <a class="header-anchor" href="#困之坤" aria-label="Permalink to “困之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>六鷁退飛，為襄敗祥。陳師合戰，左股夷傷。遂以薨崩，霸功不成。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>詳《蹇》之《蠱》。此與上乾皆用遇卦《困》象。</p><h3 id="困之屯" tabindex="-1">困之屯 <a class="header-anchor" href="#困之屯" aria-label="Permalink to “困之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>匍匐出走，驚惶悼恐。白虎生孫，蓐收在後。居中無咎。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>震走，坎蹇，故匍匐出走。震驚，坎懼，故曰悼恐。互艮為虎，震白，故曰白虎。震為生，艮為孫，伏兌為秋，故曰蓐收。《月令》：&quot;孟秋之月，其帝少昊，其神蓐收&quot;，《國語》：&quot;史囂曰：天之刑神也&quot;。震為後，坎為中。○生，宋元本作王，依汲古。</p><h3 id="困之蒙" tabindex="-1">困之蒙 <a class="header-anchor" href="#困之蒙" aria-label="Permalink to “困之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>庇廬不明，使孔德妨。女孽亂國，虐政傷仁。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>艮為廬，坤坎皆為黑，故不明。震為孔，言齊人饋女樂妨害孔子不安其位也。坤為女、為孽、為國、為亂、為虐政。○孔，汲古作禮，依宋元本。</p><h3 id="困之需" tabindex="-1">困之需 <a class="header-anchor" href="#困之需" aria-label="Permalink to “困之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>鼫鼠四足，不能上屋。顏氏淑德，未有爵祿。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>詳《萃》之《乾》。</p><h3 id="困之訟" tabindex="-1">困之訟 <a class="header-anchor" href="#困之訟" aria-label="Permalink to “困之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>襄送季女，至於盪道。齊子旦夕，流連久處。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《大過》。元本作久流連處，依宋本。</p><h3 id="困之師" tabindex="-1">困之師 <a class="header-anchor" href="#困之師" aria-label="Permalink to “困之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>麞鹿逐牧，飽歸其居。還反次舍，樂得自如。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《比》。反，汲古作於，依宋元本。</p><h3 id="困之比" tabindex="-1">困之比 <a class="header-anchor" href="#困之比" aria-label="Permalink to “困之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>望尚阿衡，太宰周公。藩屏輔弼，福祿來同。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《鼎》。三四句宋元本作屏藩湯武，立為侯王，依汲古，惟汲古屏訛居。</p><h3 id="困之小畜" tabindex="-1">困之小畜 <a class="header-anchor" href="#困之小畜" aria-label="Permalink to “困之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>開郭宏緒，王跡所基，報以八子，功德俟時。定四年，武王母弟八人，周公為太宰。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>基，汲古作居，報以八子作振以公子，均依宋元本。巽為緒，伏震為開、為王、為跡、為子，伏坤，卦數八，故曰八子。艮為時，艮止，故俟時。</p><h3 id="困之履" tabindex="-1">困之履 <a class="header-anchor" href="#困之履" aria-label="Permalink to “困之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>八會大都，饒富有餘。安民利國，可以長居。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>巽數八，坤為大都、為饒富、為民、為國，巽為利、為長。○八，汲古作入，依宋元本，言八方會於大都也。</p><h3 id="困之泰" tabindex="-1">困之泰 <a class="header-anchor" href="#困之泰" aria-label="Permalink to “困之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>陰雲四方，日在中央。人雖昏霧，我獨昭明。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>坤為雲、為方，震卦數四，故曰陰雲四方。乾為日，震為人，坤為霧，乾為大明，言震人居坤霧之中，雖昏黯無礙於乾之明也。</p><h3 id="困之否" tabindex="-1">困之否 <a class="header-anchor" href="#困之否" aria-label="Permalink to “困之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>魃為災虐，風吹雲卻。欲上不得，復歸其宅。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>坤為鬼、為惡、為災，故曰魃為災虐。坤雲巽風，而巽為退，故曰風吹雲卻。艮止，故不得上。○第二句汲古作大風吹卻，非，依宋元本。魃，各本皆訛為薄，茲依《小畜》之《中孚》校。《詩大雅》&quot;旱魃為虐&quot;《毛傳》：&quot;魃，旱神也&quot;。</p><h3 id="困之同人" tabindex="-1">困之同人 <a class="header-anchor" href="#困之同人" aria-label="Permalink to “困之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>昭昭略略，非忠信客。言多反覆，以黑為白。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>離明，故曰昭昭。昭昭略略，似當時方言，形容不忠之象貌。巽為客，乾為信、為言，離正反兌口相對為有言，故曰言多反覆。巽為白，乾天為玄、為黑。○多，宋元本作語，依汲古。</p><h3 id="困之大有" tabindex="-1">困之大有 <a class="header-anchor" href="#困之大有" aria-label="Permalink to “困之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>三女為姦，俱遊高園。背室夜行，與伯笑言。禍反及身，冤無所禱。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>此用《困》象。互離，卦數三，故曰三女。坎為姦，伏艮為高園。坎為室、為夜，艮為背，故曰背室夜行。伏震為行，兌笑言，坎為禍，艮為身，艮者震之反，故曰禍反及身。坎為冤，震為禱。又多用困伏象。○反及，宋元本作及乃，無所作死誰，均依汲古。園，汲古作國，依宋元本。</p><h3 id="困之謙" tabindex="-1">困之謙 <a class="header-anchor" href="#困之謙" aria-label="Permalink to “困之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>涉屍留鬼，大斧所視。文昌司過，簡公亂死。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>坤為屍、為鬼，涉疑為移或徙之訛，言屍去而鬼留也。伏兌為斧，離為視，坤為文，震為竹簡、為公，坤為亂、為死，《晉書天文志》：&quot;文昌六星，四曰司農司隸，五曰司命&quot;。簡公為陳成子所弒，見《論語》。</p><h3 id="困之豫" tabindex="-1">困之豫 <a class="header-anchor" href="#困之豫" aria-label="Permalink to “困之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>大足長股，利出行道。囷倉充盈，疏齒善市。宜錢富家，事得萬倍。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>震為大足。伏巽為長、為股、為利，震為大塗、為行，故曰利出行道。艮為囷倉，坤多，故曰充盈。伏兌為齒，震形兌而長，故曰疏齒。伏巽為市，坤為財貨，故曰宜錢富有。艮為家，伏巽為倍，坤多，故曰萬倍。按：大足、長股、疏齒，蓋皆夷狄名。《淮南墜形訓》有跂踵民。大荒北經曰：跂踵國在拘纓東，其為人大兩足，亦曰大踵，大踵即大足長股，亦西方戎名，詳《比》之《蹇》，疏齒疑即淮南所謂鑿齒民，在海外東南方。善市即善賈也。○第五句汲古作宜以錢富，囷倉訛困合，均依宋元本。</p><h3 id="困之隨" tabindex="-1">困之隨 <a class="header-anchor" href="#困之隨" aria-label="Permalink to “困之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>筐筥錡釜，可活百裡。伊氏鼎俎，大福所起。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>震為筐筥錡釜。艮為裡，震為百、為生，故曰可活百裡。《史記》：&quot;晉滅虞，以百裡奚為秦繆夫人媵。&quot;《呂氏春秋》：&quot;百裡奚飯牛於秦&quot;，蓋其職賤，所司皆筐筥錡釜之事，反因以得活而相秦也。伊尹以鼎鼐乾湯，震為鼎俎、為伊吾。伊，歌聲也。○可，汲古作河，依宋元本。百裡，宋元本作百口，汲古作百呂，依局本。</p><h3 id="困之蠱" tabindex="-1">困之蠱 <a class="header-anchor" href="#困之蠱" aria-label="Permalink to “困之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>升高登虛，欲有望候。駕之北邑，與喜相扶。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>巽為高，艮為墟、為望，震為登、為南，震反為艮，則北矣。艮為邑，故曰駕之北邑。震為喜，艮為扶，正反艮，故曰相扶。</p><h3 id="困之臨" tabindex="-1">困之臨 <a class="header-anchor" href="#困之臨" aria-label="Permalink to “困之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>用彼嘉賓，政平且均。螟蟲不作，民得安寧。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>伏巽為暝蟲，震為嘉賓，坤為政、為平均。</p><h3 id="困之觀" tabindex="-1">困之觀 <a class="header-anchor" href="#困之觀" aria-label="Permalink to “困之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>桃夭少華，婚悅宜家。君子樂胥，長利止居。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>巽為桃，兌為華、為少，故曰少華。兌為悅，《詩周南》：&quot;桃之夭夭，灼灼其華；之子於歸，宜其室家&quot;。艮為家、為君子，伏震為樂，巽為利，艮為居。長利止居，言女嫁得所也。○華，宋元本作葉，依汲古。三五伏兌。</p><h3 id="困之噬嗑" tabindex="-1">困之噬嗑 <a class="header-anchor" href="#困之噬嗑" aria-label="Permalink to “困之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>東行失旅，不知何處。西歸無配，莫與笑語。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震為東、為行旅，互坎故失旅，故不知何處。坎位西，坎孤，故無配，故無笑語。○配，宋元本作妃，依汲古。</p><h3 id="困之賁" tabindex="-1">困之賁 <a class="header-anchor" href="#困之賁" aria-label="Permalink to “困之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>玩好亂目，巧聲迷耳。賊敗貞良，君受其殃。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>坎耳離目，坎隱伏，故曰迷耳。離亂，故曰亂目。震為聲，正反震，故曰巧聲。坎為賊，艮為貞良，震為君。○殃，宋元本作咎，依汲古。</p><h3 id="困之剝" tabindex="-1">困之剝 <a class="header-anchor" href="#困之剝" aria-label="Permalink to “困之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>明德孔嘉，萬歲無虧。駕龍巡狩，王得安所。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>艮為明，坤虛為孔、為萬歲，伏乾為龍、為王、為行，故曰駕龍巡狩。○安所，汲古作所安，依宋元本。</p><h3 id="困之復" tabindex="-1">困之復 <a class="header-anchor" href="#困之復" aria-label="Permalink to “困之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>同本異葉，安仁尚德。東鄰慕義，來興古國。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>震木，故曰本、曰葉。坤為安，震為仁德、為東、為鄰，坤為義、為國。○古，宋元本作吾。按：綿瓞瓞詩古公亶父傳：古公，猶先公，茲曰古國，義與毛異。</p><h3 id="困之無妄" tabindex="-1">困之無妄 <a class="header-anchor" href="#困之無妄" aria-label="Permalink to “困之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>戴山崔嵬，日高無頹。君王我德，賜以嘉國。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>乾為山，艮為戴，在乾下，故曰戴山崔嵬。艮為日，巽為高，乾為君王、為德，艮為我。我德，言德我也。艮為國，震為嘉。○日，宋元本訛曰，王作主，嘉作家，均依汲古。我，汲古作好，依宋元本。</p><h3 id="困之大畜" tabindex="-1">困之大畜 <a class="header-anchor" href="#困之大畜" aria-label="Permalink to “困之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>築室合歡，千里無患。周公萬年，佑我二人，壽以高遠。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>艮為室，震為歡，正反震相對，故曰合歡。坤為千里、為患，坤伏，故無患。艮為壽、為高，乾為遠。○二，汲古作三，依宋元本。宋元本無末句，依汲古。</p><h3 id="困之頤" tabindex="-1">困之頤 <a class="header-anchor" href="#困之頤" aria-label="Permalink to “困之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>養雞生雛，畜馬得駒。明堂太學，君子所居。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>伏巽為雞，震為馬，艮少，故曰雛、曰駒。艮為明堂、為君子，坤文，故曰太學。</p><h3 id="困之大過" tabindex="-1">困之大過 <a class="header-anchor" href="#困之大過" aria-label="Permalink to “困之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>雷行相逐，無有休息。戰於平陸，為夷所覆。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《泰》。</p><h3 id="困之坎" tabindex="-1">困之坎 <a class="header-anchor" href="#困之坎" aria-label="Permalink to “困之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>委蛇循河，北至海涯。涉厯要荒，君世無他。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>坎為曲，故曰委蛇。伏巽為蛇。坎位北，伏兌為海，互震為君。○北至，汲古作至北，君作在，從宋元本。</p><h3 id="困之離" tabindex="-1">困之離 <a class="header-anchor" href="#困之離" aria-label="Permalink to “困之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>鴻聲大視，高舉神化。背昧嚮明，以通福功。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>伏震為鴻、為聲，離為視，巽為高，互兌為夜，故曰背昧。離明，故曰嚮明。伏震為福。○向，汲古作皆，形訛，依宋元本。通，宋元本作道，依汲古。</p><h3 id="困之鹹" tabindex="-1">困之鹹 <a class="header-anchor" href="#困之鹹" aria-label="Permalink to “困之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>比目四翼，來安吾國。福喜上堂，與我同床。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>後三句汲古作&quot;安我邦國，上下無患，為吾家福&quot;，從宋元本。鹹伏損，上艮為目，三至上正反艮，故曰比目。震為翼，卦數四，故曰四翼。艮為安、為國、為堂、為床，震為福喜。</p><h3 id="困之恆" tabindex="-1">困之恆 <a class="header-anchor" href="#困之恆" aria-label="Permalink to “困之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>先縠彘季，反謀桓子。不從元帥，遂行挑戰，為荊所敗。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>《左傳宣十二年》：&quot;楚子圍鄭，荀林父帥師救之，及河，聞楚與鄭平桓子欲歸，彘子曰不可，遂挑戰晉師，敗績&quot;。巽為縠、為彘。震為桓、為子，巽震卦相反，故曰反謀桓子。震為元帥、為戰、為荊楚，兌毀，故曰敗。○不，元本訛子，依宋本、汲古。先縠，汲古作士縠，依宋元本。先縠，彘子名。</p><h3 id="困之遯" tabindex="-1">困之遯 <a class="header-anchor" href="#困之遯" aria-label="Permalink to “困之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>三頭六足，欲盜東國。顏子在庭，禍滅不成。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>乾為頭，艮數三，故曰三頭。乾數六，故曰六足。伏震為足、為東，艮為國，故曰東國。巽為盜，艮為顏、為庭，坤為禍滅，坤伏，故不成。三頭，似指魯三家。顏子或指顏淵。○庭，宋元本作邇，依汲古。</p><h3 id="困之大壯" tabindex="-1">困之大壯 <a class="header-anchor" href="#困之大壯" aria-label="Permalink to “困之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>緣山升木，中墮於谷。子輿失勞，黃鳥哀作。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>通《觀》。艮為山谷，巽為木、為隕落，故曰中墜於谷。震為輿、為子、為黃，伏艮為鳥，坤為哀。《左傳文六年》：&quot;秦伯任好卒，以子車氏之三子殉，國人哀之，為賦黃鳥&quot;。子輿，即子車也。○勞疑為勢或榮之訛。</p><h3 id="困之晉" tabindex="-1">困之晉 <a class="header-anchor" href="#困之晉" aria-label="Permalink to “困之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>南有嘉魚，駕黃取鱗。魴鯉彌彌，利來無憂。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>離為南，坤為魚、為黃。黃曵欣穡皆魚名。嘉魚，《小雅》篇名。</p><h3 id="困之明夷" tabindex="-1">困之明夷 <a class="header-anchor" href="#困之明夷" aria-label="Permalink to “困之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>邃炁作雲，蒙覆大君。塞聰閉明，殷人賈傷。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>震為大君，坤為雲氣，炁氣同。坤雲在震上，故曰蒙覆大君。坎耳聰，離目明，坤為閉塞，故曰塞聰閉明。震為子，殷，子姓。震為商賈，故曰殷人賈傷。○君，汲古作臣，非，依宋元本。賈，疑訛字。易林屢以震為孩子，箕子之明夷，蓋讀箕子為孩子，孩子為昏蒙之代名，專指紂，故曰蒙覆大君，足證以箕子為紂臣之誤。</p><h3 id="困之家人" tabindex="-1">困之家人 <a class="header-anchor" href="#困之家人" aria-label="Permalink to “困之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>舉翅攄翼，跂望南國。延頸卻縮，未有所得。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>此用《困》象。伏《賁》。震為翅翼、為攄舉、為南，艮為國，下離，故跂望南國。艮為頸，在上，故曰延頸。震為返，故卻縮。坎失，故未有所得。</p><h3 id="困之睽" tabindex="-1">困之睽 <a class="header-anchor" href="#困之睽" aria-label="Permalink to “困之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>坎中蝦蟆，乍盈乍虛。三夕二朝，形消無餘。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦《困》象。巽為蝦蟆，下坎，故曰坎中蝦蟆。坎盈離虛，坎為夕，離卦數三，故曰三夕，言晦日三十也。伏震為朝，兌卦數二，故曰二朝。按：張衡靈憲雲：嫦娥竊不死之藥，遂託身於月，是為蟾蜍。坎中蝦蟆，即月中蝦蟆也，言月前盈後虛，至月朔而消滅無有也。</p><h3 id="困之蹇" tabindex="-1">困之蹇 <a class="header-anchor" href="#困之蹇" aria-label="Permalink to “困之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>重弋射隼，不知所定。質疑蓍龜，執可避之。國安上樂，宜利止居。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>兵寇不至，民無騷憂。此仍用《困》象。《詩鄭風》：&quot;弋鳧與雁&quot;，《傳》以繩系矢而射，曰弋。巽為弋，正反巽，故曰重弋。伏艮為隼，震為射，巽進退不果，故曰不知所定。坎為筮，故曰質疑。巽為蓍，離為龜，坎為避，孰可避之，言孰可避免也。艮為國、為土，震樂，巽利。○首句宋元本作僮子射御，汲古作僮或射御。僮，重之訛，或弋之訛，茲依《中孚》之《復》校。可避之，之與龜韻，宋元本作孰知所避，茲依汲古。七八句疑衍文，故不釋。</p><h3 id="困之解" tabindex="-1">困之解 <a class="header-anchor" href="#困之解" aria-label="Permalink to “困之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>陰淫寒疾，水離其室。舟楫大作，傷害黍稷。民飢於食，不無病厄。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>離，汲古作流，從宋元本。楫，元本作戢，非，依宋本、汲古。坎為陰寒、為疾、為室，震為楫、為黍稷，坎破，故傷害黍稷。坎為民、為厄。離虛，故飢。</p><h3 id="困之損" tabindex="-1">困之損 <a class="header-anchor" href="#困之損" aria-label="Permalink to “困之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>離友絕朋，巧言讒慝。覆白汙玉，顏叔哀哭。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>艮友在外，故曰離。兌為朋，兌附決，故曰絕。正反震，故曰巧言讒慝。震為白、為玉，坤蒙閉，故曰覆白汙玉。覆，掩也。艮為顏、為叔，兌為哭。顏叔未詳。○慝，宋元本作匿，依汲古。</p><h3 id="困之益" tabindex="-1">困之益 <a class="header-anchor" href="#困之益" aria-label="Permalink to “困之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>童女無媒，不宜動搖。安其室廬，傅母何憂。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>巽為女，艮少，故曰童女。艮止，故不宜動搖，言宜貞靜也。艮為室廬，艮止，故曰安。坤為母，震樂，故傅母不憂也。古女子皆有傅母以為教導。</p><h3 id="困之夬" tabindex="-1">困之夬 <a class="header-anchor" href="#困之夬" aria-label="Permalink to “困之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>作兇造患，北檄困貧。東與禍連，傷我左跟。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦《困》象。困通賁。坎為兇患、為北檄，以木簡為牘，長尺二寸，以為徵召。坎陷，故曰困。離虛，故貧。《後漢安帝紀》：&quot;民窮困道路，欲歸本郡，在所為封長檄&quot;。震為東，坎為禍、為傷，震為左、為跟。○檄，汲古作榭，禍作福，均依宋元本。左，宋元本作老，依汲古。</p><h3 id="困之姤" tabindex="-1">困之姤 <a class="header-anchor" href="#困之姤" aria-label="Permalink to “困之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>東南其戶，風雨不處。睆仁人，父子相保。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>乾為門戶，巽居東南，故曰東南其戶。巽風進退無常，故曰不處。《毛詩》：&quot;睆，好貌&quot;。乾為仁人、為父，伏震為子。○睆，汲古作●睨，宋元本作睨。丁雲睨當為睆是也，故從釋文。</p><h3 id="困之萃" tabindex="-1">困之萃 <a class="header-anchor" href="#困之萃" aria-label="Permalink to “困之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>被髪獸心，難與比鄰。來如飄風，去似絕弦，為狼所殘。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>巽為髪，艮為獸，坤為心，巽為飄風、為繩，故為弦。兌毀，故絕弦。艮為狼，兌口，故曰為狼所殘，言為狼所噬也。</p><h3 id="困之升" tabindex="-1">困之升 <a class="header-anchor" href="#困之升" aria-label="Permalink to “困之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>天覆地載，日月運照。陰陽允作，方內四富。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>坤為地，伏乾為天、為日，兌為月，坤為方、為多，故為富。震卦數四，故曰四富。</p><h3 id="困之困" tabindex="-1">困之困 <a class="header-anchor" href="#困之困" aria-label="Permalink to “困之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>席多針刺，不可以臥。動而有悔，言行俱過。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>坎為針刺，下坎互大坎，故多針刺。伏賁。賁下互坎，上互震，震為席，與坎連，故席多針刺。艮為臥，三至上正反艮，故不可臥。亦正反震，故言行俱過也。</p><h3 id="困之井" tabindex="-1">困之井 <a class="header-anchor" href="#困之井" aria-label="Permalink to “困之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>桀亂無道，民散不聚。背室棄家，君孤出走。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>離為惡人，故曰桀。震為大塗，震伏，故曰無道。坎為眾、為民。風散，故曰不聚。艮為室家，艮伏，故曰背、曰棄。震為君，坎為孤，震伏，故曰出走。</p><h3 id="困之革" tabindex="-1">困之革 <a class="header-anchor" href="#困之革" aria-label="Permalink to “困之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>申酉稷射，陰慝萌作。荷葭載牧，泥塗不白。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>巽先天居申，兌後天居酉，丁雲《穀梁定十五年傳》日下稷註：稷，日仄也。下稷為晡時，伏震為射。申酉稷射者，言日至申酉晡時而射也。伏坤為陰慝，震為萌芽，故曰萌作。伏艮為荷，巽為葭，坤為牧，坎為泥塗，巽為白，坎隱，故不白。○稷射，汲古作敗時，依元本。荷，宋元本作柯，依汲古。葭，疑蓑之訛，《詩》：&quot;何蓑何笠&quot;是也。</p><h3 id="困之鼎" tabindex="-1">困之鼎 <a class="header-anchor" href="#困之鼎" aria-label="Permalink to “困之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>踝踵足傷，左趾病瘍。失旅後時，利走不來。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《履》。</p><h3 id="困之震" tabindex="-1">困之震 <a class="header-anchor" href="#困之震" aria-label="Permalink to “困之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>四足俱走，駑疲在後。俱戰不勝，敗於東野。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>震卦數四，故曰四足。震為後，坎勞，故曰駑疲在後。震為戰，坎陷，故不勝，故敗。震東，艮野。○俱戰，宋元本作戰既，從汲古。</p><h3 id="困之艮" tabindex="-1">困之艮 <a class="header-anchor" href="#困之艮" aria-label="Permalink to “困之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>塗行破車，醜女無媒。莫適為偶，孤困獨居。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>互震為大塗、為行、為車，坎破，故曰塗行破車。伏兌為女，離為惡人，故曰醜女。坎為孤，艮為鰥，故曰孤困獨居。○偶，汲古作耦，依宋元本。</p><h3 id="困之漸" tabindex="-1">困之漸 <a class="header-anchor" href="#困之漸" aria-label="Permalink to “困之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>拊髀大笑，不知憂懼。開立大路，為王所召。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>髀，《說文》股也。巽為股，艮手，故曰拊髀。伏震為笑，坎為憂懼，兌悅，震樂，故不知憂懼。震為大路、為王、為召。○王，宋元本作主，依汲古。</p><h3 id="困之歸妹" tabindex="-1">困之歸妹 <a class="header-anchor" href="#困之歸妹" aria-label="Permalink to “困之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>伯圭東行，與利相逢。出既遭時，孰不相知。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>震為伯、為玉，故曰伯圭。伯圭善貨殖，見《史記》、《孟子》。伏巽為利，故與利相逢。震為出、為時。○圭，汲古訛主，依宋元本。宋元本時訛昧，下多憂不成兇四字，均依汲古。</p><h3 id="困之豐" tabindex="-1">困之豐 <a class="header-anchor" href="#困之豐" aria-label="Permalink to “困之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>東行賊家，鄭伯失辭。國無貞良，君受其殃。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>震為東行，巽為賊，伏艮為家。震為伯，伏坎為平、為鄭，故曰鄭伯。正反震，故失詞。艮為國、為貞良，艮伏，故無。震為君，離為殃。東行賊家，指桓十五年鄭厲公居櫟，是東行也，後自櫟入。鄭殺傅瑕原繁逐昭公，是賊家也，殺原繁言不順，是失詞也。</p><h3 id="困之旅" tabindex="-1">困之旅 <a class="header-anchor" href="#困之旅" aria-label="Permalink to “困之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>前屈後曲，形體飭急。絞黑大索，困於請室。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>通《節》。坎為屈曲，艮前，震後，故曰前屈後曲。艮為形體，兌剛魯，附決，故曰飭。急，猶緊急也。巽為索，坎為黑，正反巽故曰絞。絞，縛也。艮為室，震為請，坎陷，故曰困於請室。請室，大臣待罪之所也。○飭，汲古作勁，非，依宋元本。請，宋元本訛清，依汲古。</p><h3 id="困之巽" tabindex="-1">困之巽 <a class="header-anchor" href="#困之巽" aria-label="Permalink to “困之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>鼓翼大喜，行婚飲酒。嘉彼諸薑，樂我皇考。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>伏震為翼、為鼓、為喜。兌口為飲，伏坎為酒、為婚，故曰行婚飲酒。巽為薑，重巽，故曰諸薑。伏震為父，為大，故曰皇考。○翼，宋元本作腋，依汲古。婚，汲古作嫁，依宋元本。○言大喜之故在將婚飲酒也。</p><h3 id="困之兌" tabindex="-1">困之兌 <a class="header-anchor" href="#困之兌" aria-label="Permalink to “困之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>狐嘈向城，三旦悲鳴，邑主大驚。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>伏艮為狐、為城，震為鳴，故曰嘈。嘈，啼也。震為旦，數三，故曰三旦。互坎為憂，故曰悲鳴。艮為邑，震為主、為驚，皆用伏象。此必有故事，為今所不能考，或以吳廣詐狐鳴事說之，似非。○宋元本首句多國將有事四字，將林詞奇肆突兀之神全失，故依汲古。</p><h3 id="困之渙" tabindex="-1">困之渙 <a class="header-anchor" href="#困之渙" aria-label="Permalink to “困之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>明德克敏，重華貢舉。放勛徵用，浚哲蒙佑。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>震為德，艮為明，故曰明德。震為華，正反震，故曰重華。震又為帝，故又曰放勛。○克，汲古作光，依宋元本。言堯舜，天下蒙福。</p><h3 id="困之節" tabindex="-1">困之節 <a class="header-anchor" href="#困之節" aria-label="Permalink to “困之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>秋隼冬翔，數被嚴霜。甲兵充庭，萬物不生。雞犬夜鳴，民人擾驚。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>詳《鼎》之《觀》。○充，汲古作克，依宋元本。犬，宋元本作父，依汲古。人，元本、汲古作大，依宋元。</p><h3 id="困之中孚" tabindex="-1">困之中孚 <a class="header-anchor" href="#困之中孚" aria-label="Permalink to “困之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>絲紵布帛，人所衣服。摻摻女手，紡績善織。南國饒有，取之有息。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>巽為絲紵布帛。震為衣，艮手與巽連體，故曰女手。巽為紡績、為織。艮為國，與震連，故曰南國。震生，故有息。</p><h3 id="困之小過" tabindex="-1">困之小過 <a class="header-anchor" href="#困之小過" aria-label="Permalink to “困之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>鳳有十子，同巢共母。仁聖在位，歡以相保，興彼周魯。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>艮為鳳，震為子，兌數十，故曰十子。艮為巢，巽為母，震為仁、為歡、為周，兌為魯。○三四五句汲古作&quot;歡以相保，富市之地，多財積谷&quot;，依宋元本，此似指武王同母兄弟十人，故曰共母。而十人之中以周公為最仁聖，周魯皆賴以興也。</p><h3 id="困之既濟" tabindex="-1">困之既濟 <a class="header-anchor" href="#困之既濟" aria-label="Permalink to “困之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>雄雞不晨，雌鳴且呻。志疪心離，三旅生哀。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>此似用遇卦《困》象。巽為雞，震為晨、為雄，震伏，故不晨。巽為雌，兌口為鳴、為呻，坎為心志、為疾，故曰疪。疪痺同，《說文》濕病也。《內經》曰風痛也。亦巽象也。○鳴且，汲古訛雞具，依宋元本。呻，宋元本訛伸，疪作疵，生作出，均依汲古。旅，閭通用。三旅，屈子也。雌鳴指鄭袖。志疪心離，言作離騷。</p><h3 id="困之未濟" tabindex="-1">困之未濟 <a class="header-anchor" href="#困之未濟" aria-label="Permalink to “困之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>光祀春城，陳寶雞鳴。陽明失道，不能自守，消亡為咎。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>詳《大有》之《井》。首句汲古作光休出城，依宋元本。明，宋元本作鳥，為作無，均依汲古。元本下多&quot;舉事不成，自取兇咎&quot;二句，依汲古。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
